def main():
    import sys
    a, b, c = map(int, sys.stdin.readline().split())
    total = a + b + c
    if total == 0:
        print(0)
        return
    if total % 3 != 0:
        print(-1)
        return
    max_color = max(a, b, c)
    if max_color == total:
        print(0)
    else:
        print(total - max_color)

